result=result.match(regex);
result=result[1];
result=decodeURIComponent(result);
result=result.replace("http://","https://");
result=result.replace("www.comicimgs.com","img.comicimgs.com");
result=result.replace(/.*\/ref\/\?r=/,"");
result;

ruleToc.chapterList:
@js:
var list = [];
if (result.match("开始浏览") == null) { //判断目录
    var regex = /href="(content-.+-\d+.html)">(.*)<\/a>/g;
    var match;
    while ((match = regex.exec(result)) !== null) {
        list.push({
            m: match[1],
            n: match[2]
        })
    }
} else {
    var regex = /href="(.*)" s.*(开始浏览)/;
    var match = result.match(regex);
    list.push({
        m: match[1],
        n: match[2]
    });
}
list

