  var u = result.match(/target=(https?.*.html)/)[1]
  url = decodeURIComponent(u)
  id = url.match(/chapter\/(.+)\.html/)[1]
  burl = 'https://www.ibusread.com/api/chapter/detail,'
  body = String('id='+id)
  head = { "referer": url }
